    "professor": "Serçin Özlem Çalışkan",
    "question": "Bir nöronun dinlenim membran potansiyeli oluşumunda en fazla katkı sağlayan iyon hangisidir?",
    "options": [
      {
        "letter": "A",
        "text": "Kalsiyum"
      },
      {
        "letter": "B",
        "text": "Sodyum"
      },
      {
        "letter": "C",
        "text": "Magnezyum"
      },
      {
        "letter": "D",
        "text": "Potasyum"
      },
      {
        "letter": "E",
        "text": "Klor"
      }
    ],
    "answer": "D",
    "open_answer": "",
